fn set_field(value: &mut Value, key: &str, replacement: Value) {
    *field_mut(value, key) = replacement;
}

fn field_mut<'a>(value: &'a mut Value, key: &str) -> &'a mut Value {
    map_mut(value)
        .iter_mut()
        .find_map(|(field, value)| match field {
            Value::Text(field) if field == key => Some(value),
            _ => None,
        })
        .unwrap_or_else(|| panic!("missing descriptor field {key}"))
}

fn map_mut(value: &mut Value) -> &mut Vec<(Value, Value)> {
    let Value::Map(entries) = value else {
        panic!("descriptor must be a map")
    };
    entries
}

